// LEGO Technic 42109, the App-Controlled Top Gear Rally Car, as its instructions build it: the body with its
// Control+ hub and two motors, the front wheels steered through a rack by the L motor and the rear wheels driven
// through a differential by the XL motor.
Robot lego_42109 {
    intent "LEGO Technic 42109 App-Controlled Top Gear Rally Car, an Ackermann base"

    Ackermann chassis(ref = "lego_42109_chassis")

    Motor motor_rear(ref = "lego_controlplus_xl_motor", glue = (-0.0753, 0.024, 0.032, 0, -1, 0))

    Standard wheel_front_left(ref = "lego_42109_front_wheel", glue = (0.076, 0.056, -0.0032, 0, 1, 0))
    Standard wheel_front_right(ref = "lego_42109_front_wheel", glue = (0.076, -0.056, -0.0032, 0, -1, 0))
    Standard wheel_rear_left(ref = "lego_42109_rear_wheel", glue = (-0.076, 0.0588, 0, 0, 1, 0))
    Standard wheel_rear_right(ref = "lego_42109_rear_wheel", glue = (-0.076, -0.062, 0, 0, -1, 0))
}

files.world:
World drive_check {
    physics(gravity = (0, 0, -9.81))
    spawn(robot = @core/lego_42109, pose = (0, 0, 0.03, 0, 0, 0, 1))
